insert into features (name, description, class_id, subclass_id, level_required) values
  ('Affirmation', 'Whenever your Pokémon knock out an opposing Pokémon, or whenever they score a critical hit, they gain temporary hit points equal to your Attack or Special Attack modifier', (select id from classes where name = 'Ace trainer'), null, 1),
  ('Improved attacks', 'Whenever your Pokémon hits with an attack, they deal additional damage equal to your Attack or Special Attack modifier, depending on which Attack or Special Attack modifier your Pokémon is adding to their attack respectively (already added to all your Pokémon)', (select id from classes where name = 'Ace trainer'), null, 1),
  ('Intimidate', '3/day, as an action, you can make a target Pokémon’s Attack or Special Attack stat -2 for the remainder of an encounter. You need a line of sight to the target within 40ft. This penalty can stack with itself', (select id from classes where name = 'Ace trainer'), null, 2),
  ('Stat increase', 'Choose two different Trainer Stats to increase by 1', (select id from classes where name = 'Ace trainer'), null, 3),
  ('Advanced class', 'Choose an Advanced Class', (select id from classes where name = 'Ace trainer'), null, 3),
  ('Constructive critisicm', 'You can discern why you Pokémon’s attacks are failing to get through an opposing Pokémon’s defenses. Whenever your Pokémon misses with an attack, the next time they use that attack on the same target add 2 to their Accuracy Check. This bonus can stack with itself, if your Pokémon continues to miss against the same target with the same Move. Once your Pokémon hits, with that Move against the same target, Constructive Criticism’s bonus is reset', (select id from classes where name = 'Ace trainer'), null, 4),
  ('Press', 'You can push your Pokémon harder through intense motivation. As an action, one of your Pokémon within line of sight has its stats raised by 2 until the end of an encounter. That Pokémon takes X damage, where X is 8 minus either your Attack or Special Attack modifier. Be careful, the repeated use of Press on your Pokémon may push them too far and you could begin to negatively affect their loyalty to you', (select id from classes where name = 'Ace trainer'), null, 5),
  ('Pokémon master', 'You become a master commander to your Pokémon. As long as it’s your Pokémon, they cannot disobey commands regardless of their loyalty. This does not improve their relationships with you, your Pokémon simply cannot disobey your commands', (select id from classes where name = 'Ace trainer'), null, 6),
  ('Stat increase', 'Choose two different Trainer Stats to increase by 1', (select id from classes where name = 'Ace trainer'), null, 7),
  ('Advanced class', 'Choose an Advanced Class', (select id from classes where name = 'Ace trainer'), null, 7),
  ('Taskmaster', 'You learn how to best to push your Pokémon to their limits without causing them any distress. Whenever you use any Press actions, cure your Pokémon of being Stunned or Confused. Also restore any temporarily lowered stats to their normal stats. Your Pokémon’s loyalty is not negatively affected by repeated uses of any Press actions', (select id from classes where name = 'Ace trainer'), null, 8),
  ('Battle frenzy', 'You know when enemy Pokémon are nearing their limits and your Pokémon begin to mirror your excitement during battle. As an action, you can identify whether or not a target Pokémon is at or below half of its full HP. If a target is, one of your active Pokémon’s Speed is raised by 2 as long as it is pursuing or attacking that Pokémon', (select id from classes where name = 'Ace trainer'), null, 9),
  ('Break through', 'You see every weakness in every Pokémon just by studying them for a couple of seconds and specify the point while instructing your Pokémon. 3/day, as an action, you can target a Pokémon with Break Through! For the remainder of the encounter, your Pokémon can use both their Attack or Special Attack against either of the target’s Defense or Special Defense in order to hit during accuracy check regardless of the attack’s preference. In addition, after using Break Through, the target’s Defense and Special Defense values are revealed to you', (select id from classes where name = 'Ace trainer'), null, 10),
  ('Stat increase', 'Choose two different Trainer Stats to increase by 1', (select id from classes where name = 'Ace trainer'), null, 11),
  ('Advanced class', 'Choose an Advanced Class', (select id from classes where name = 'Ace trainer'), null, 11),
  ('Press on', 'You can urge your Pokémon to make one more desperate attack. Once per day, you can issue a command to one of your Pokémon who was just knocked out during the last round of combat. If it does, you must immediately return it to its Poké Ball during your turn after it acts. If the Pokémon is further damaged to -100% HP, you may still need to roll a death saving throw if the foe had lethal intent', (select id from classes where name = 'Ace trainer'), null, 12),
  ('Battle experience', 'You have enough battles behind you that you have a good idea of what to expect, or when to expect the unexpected. As an action, you may target an opposing Pokémon and identify whether or not the Pokémon has a super-effective Move against any of your active Pokémon. If they do, you are informed of what attacks they are', (select id from classes where name = 'Ace trainer'), null, 13),
  ('Finish it', 'Your Pokémon’s attacks have more power in them as a foe gets nearer to being knocked out. If a target of one of your Pokémon’s damaging attacks are lowered to 10 or less HP, it is knocked out or set to 1 HP (you decide)', (select id from classes where name = 'Ace trainer'), null, 14),
  ('Grand master', 'Your Pokémon’s strength is inspired by your presence to push out a little more with every attack. Whenever your Pokémon hits with an attack, they deal additional damage equal to twice your Attack or Special Attack stat, regardless of which Attack or Special Attack modifier your Pokémon is adding to their attack respectively. Your Pokémon may also add either your twice your Attack or Special Attack modifier to attacks without a Damage value, to deal damage with those attacks', (select id from classes where name = 'Ace trainer'), null, 15),
  ('Favored stat (attack)', 'Choice: attack', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 1),
  ('Specialist training (attack)', 'You need something very specific from your Pokémon and they have matched that urgency, honing themselves to match your favored stat. Add half of your Attack or Special Attack modifier to the attack stat of each of your Pokémon that you’ve owned for at least a week. In addition, your Pokémon’s attack stat cannot be lowered by a foe’s effect (afflictions still affect your Pokémon’s stats)', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 1),
  ('Favorable recruitment (attack)', 'Something about your personality is picked up and mirrored by wild Pokémon. Whenever you capture or obtain a new wild Pokémon, or hatch a Pokémon egg, roll the Pokémon’s Nature twice. If either nature positively influences your favored stat, you may choose that nature. If neither do, the Pokémon’s nature is the second rolled nature', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 2),
  ('Stat press (attack)', 'Your motivation may be harsh, but your Pokémon have the same goals as you when it comes to your favored combat style. Whenever you use Press on your Pokémon to temporarily raise your favored stat, you do not negatively affect your Pokémon’s loyalty and it raised +4 instead', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 3),
  ('Affliction resistance (attack)', 'Your Pokémon’s Attack stat is unaffected while Burned', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 4),
  ('Field tactics (attack)', 'Your Pokémon’s moves that use the Attack stat have the following ability: “On hit, you may move the targets up to 20ft away from you.”', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 6),
  ('Attitude adjustment (attack)', 'Your supervision can influence your Pokémon’s behavior. Once per day, after one hour of work with one of your Pokémon, you may reroll that Pokémon’s nature until you roll a nature that positively influences your favored stat', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 7),
  ('Honed skill (attack)', 'If your Pokémon have been with you for at least a week, you may teach them the Swords Dance (+2 Attack) skill after one hour of additional training. When teaching your Pokémon this Passive, you may teach it to them even if they already have the Passive, or if they already have a Passive from the same category. In this case, duplicate Passives are not redundant. The added Passive must still follow the stat passive limit of 3.', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 8),
  ('Desperate measures (attack)', 'Once per day, after two hours of work you can tutor Belly Drum to your Pokémon', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 10),
  ('Stat affirmation (attack)', 'Whenever your Pokémon hits with a move that uses the Attack stat, they gain temporary HP equal to your Attack or Special Attack modifier', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 11),
  ('Stat tactics (attack)', 'Once per week, you may spend three hours tutoring your Pokémon to learn the move Giga Impact. If you tutor an ally’s Pokémon it takes five hours.', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 12),
  ('Superior aura (attack)', 'Your glaring presence disparages enemy Pokémon and causes them to underperform during battle. 3/day, once per turn as a free action, you may disable a target(50ft) Pokémon’s Stat Passives for 10 mins', (select class_id from subclasses where name = 'Stat ace (attack)'), (select id from subclasses where name = 'Stat ace (attack)'), 13),
  ('Favored stat (defense)', 'Choice: defense', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 1),
  ('Specialist training (defense)', 'You need something very specific from your Pokémon and they have matched that urgency, honing themselves to match your favored stat. Add half of your Attack or Special Attack modifier to the defense stat of each of your Pokémon that you’ve owned for at least a week. In addition, your Pokémon’s defense stat cannot be lowered by a foe’s effect (afflictions still affect your Pokémon’s stats)', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 1),
  ('Favorable recruitment (defense)', 'Something about your personality is picked up and mirrored by wild Pokémon. Whenever you capture or obtain a new wild Pokémon, or hatch a Pokémon egg, roll the Pokémon’s Nature twice. If either nature positively influences your favored stat, you may choose that nature. If neither do, the Pokémon’s nature is the second rolled nature', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 2),
  ('Stat press (defense)', 'Your motivation may be harsh, but your Pokémon have the same goals as you when it comes to your favored combat style. Whenever you use Press on your Pokémon to temporarily raise your favored stat, you do not negatively affect your Pokémon’s loyalty and it raised +4 instead', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 3),
  ('Affliction resistance (defense)', 'While Frozen, your Pokémon get +4 during checks to break free of being Frozen', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 4),
  ('Field tactics (defense)', 'When an opponent attempts to hit your Pokémon using a move that uses the Attack stat and misses, your Pokémon may move the offender 20ft away from them', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 6),
  ('Attitude adjustment (defense)', 'Your supervision can influence your Pokémon’s behavior. Once per day, after one hour of work with one of your Pokémon, you may reroll that Pokémon’s nature until you roll a nature that positively influences your favored stat', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 7),
  ('Honed skill (defense)', 'If your Pokémon have been with you for at least a week, you may teach them the Iron Defense (+2 Defense) skill after one hour of additional training. When teaching your Pokémon this Passive, you may teach it to them even if they already have the Passive, or if they already have a Passive from the same category. In this case, duplicate Passives are not redundant. The added Passive must still follow the stat passive limit of 3.', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 8),
  ('Desperate measures (defense)', 'Once per day, after two hours of work you can tutor Unbreakable Armor to your Pokémon', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 10),
  ('Stat affirmation (defense)', 'Whenever your Pokémon is attacked with a move that uses the Attack stat and the attack misses, they gain temporary HP equal to your Attack or Special Attack modifier', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 11),
  ('Stat tactics (defense)', 'Once per week, you may spend three hours tutoring your Pokémon to learn the move Protect. If you tutor an ally’s Pokémon it takes five hours.', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 12),
  ('Superior aura (defense)', 'Your glaring presence disparages enemy Pokémon and causes them to underperform during battle. 3/day, once per turn as a free action, you may disable a target(50ft) Pokémon’s Stat Passives for 10 mins', (select class_id from subclasses where name = 'Stat ace (defense)'), (select id from subclasses where name = 'Stat ace (defense)'), 13),
  ('Favored stat (special attack)', 'Choice: special attack', (select class_id from subclasses where name = 'Stat ace (special attack)'), (select id from subclasses where name = 'Stat ace (special attack)'), 1),
