  ('Affliction resistance (special attack)', 'Your Pokémon’s Special Attack stat is unaffected while Poisoned or Toxified', (select class_id from subclasses where name = 'Stat ace (special attack)'), (select id from subclasses where name = 'Stat ace (special attack)'), 4),
  ('Field tactics (special attack)', 'Your Pokémon’s moves that use the Special Attack stat have the following abilities: “On hit, you may move the targets up to 20ft away from you.”', (select class_id from subclasses where name = 'Stat ace (special attack)'), (select id from subclasses where name = 'Stat ace (special attack)'), 6),
  ('Attitude adjustment (special attack)', 'Your supervision can influence your Pokémon’s behavior. Once per day, after one hour of work with one of your Pokémon, you may reroll that Pokémon’s nature until you roll a nature that positively influences your favored stat', (select class_id from subclasses where name = 'Stat ace (special attack)'), (select id from subclasses where name = 'Stat ace (special attack)'), 7),
  ('Honed skill (special attack)', 'If your Pokémon have been with you for at least a week, you may teach them the Fake Tears (+2 Special Attack) skill after one hour of additional training. When teaching your Pokémon this Passive, you may teach it to them even if they already have the Passive, or if they already have a Passive from the same category. In this case, duplicate Passives are not redundant. The added Passive must still follow the stat passive limit of 3.', (select class_id from subclasses where name = 'Stat ace (special attack)'), (select id from subclasses where name = 'Stat ace (special attack)'), 8),
  ('Desperate measures (special attack)', 'Once per day, after two hours of work you can tutor Migraine to your Pokémon', (select class_id from subclasses where name = 'Stat ace (special attack)'), (select id from subclasses where name = 'Stat ace (special attack)'), 10),
  ('Stat affirmation (special attack)', 'Whenever your Pokémon hits with a move that uses the Special Attack stat, they gain temporary HP equal to your Attack or Special Attack modifier', (select class_id from subclasses where name = 'Stat ace (special attack)'), (select id from subclasses where name = 'Stat ace (special attack)'), 11),
  ('Stat tactics (special attack)', 'Once per week, you may spend three hours tutoring your Pokémon to learn the move Hyper beam. If you tutor an ally’s Pokémon it takes five hours.', (select class_id from subclasses where name = 'Stat ace (special attack)'), (select id from subclasses where name = 'Stat ace (special attack)'), 12),
